"""Render the reviewed, fixed 13–15 November dataset into a complete report."""
import argparse
from collections import Counter
from datetime import datetime
from pathlib import Path
from analyze_rtt_90_180 import LOCAL, TARGETS, EARLY_RETN, dt, epoch, read_json, write_json

CLASS = {'all_controls_below_threshold':'QUIET', 'gateway_control_anomaly':'LOCAL',
         'near_without_gateway_anomaly':'NEAR', 'public_without_near_anomaly':'PUBLIC',
         'retn_only_control_anomaly':'RETN', 'uncovered_or_incomplete':'NO DATA', 'measurement_error':'MEASUREMENT ERROR'}
COLORS = ['#1768ac','#198754','#a6761d','#7a42a8','#008b8b']


def stamp(value):
    return dt(value).astimezone(LOCAL).strftime('%d.%m %H:%M:%S.%f')[:-3] if value else '—'


def num(value):
    return ('%g'%value) if value is not None else '—'


def control_text(e):
    controls = {r['target']:r for r in e['control_windows'][2]['controls']}
    if not controls:
        return 'нет проб'
    result = []
    for t in TARGETS:
        c = controls.get(t)
        early = False
        if t == TARGETS[4] and c is None:
            c = controls.get(EARLY_RETN)
            early = c is not None
        result.append((num(c['nearest']['rtt_ms'])+('*' if early else '')) if c and c['nearest'] else '—')
    offset = max(abs(c['nearest_delta_seconds']) for c in controls.values())
    return '/'.join(result)+f'; δ≤{offset:.3f}с'


def make_charts(events, probes, markers, all_events):
    specs = []
    category_colors = [('all_controls_below_threshold','#d62728','Game event; controls below limits'),
                       ('gateway_control_anomaly','#1768ac','Game event; gateway anomaly'),
                       ('near_without_gateway_anomaly','#d18b00','Game event; near-hop anomaly'),
                       ('retn_only_control_anomaly','#7749ae','Game event; RETN anomaly'),
                       ('uncovered_or_incomplete','#8c9298','Game event; no complete controls')]
    series = [dict(name=label,color=color,chart_type='Point',points=[dict(x=e['time_local'],y=e['value']) for e in events
              if e['control_windows'][2]['category']==cat]) for cat,color,label in category_colors]
    specs.append(dict(name='rtt-band-overview.png',title='Logged game Average Ping, 13–15 November 2026',
                      x_label='UTC+05:00; sparse threshold records, no interpolation; 90–119.99 ms are not sampled',
                      x_format='dd.MM HH:mm',y_label='Logged Average Ping (ms)',y_min=80,y_max=185,series=series))
    cases=[('shared-local-0055.png','2026-11-13T19:55:35+00:00','2026-11-13T19:56:05+00:00',300,'Shared short event: gateway and distant controls',None),
           ('shared-retn-0058.png','2026-11-13T19:58:03+00:00','2026-11-13T19:58:21+00:00',250,'Full episode: game 162.91 / 206.84 / 172.31 / 226.09 ms',None),
           ('game-only-0108.png','2026-11-14T20:08:30+00:00','2026-11-14T20:09:30+00:00',180,'Game 155.46 ms while ICMP controls remain low','2026-11-14T20:09:22.333+00:00'),
           ('client-fps-1448.png','2026-11-14T09:48:08+00:00','2026-11-14T09:48:22+00:00',180,'Game ~125 ms alongside client FPS/input warnings','2026-11-14T09:48:12.464+00:00')]
    for name,start,end,maximum,title,marker in cases:
        lower,upper=epoch(start),epoch(end)
        series=[dict(name=target,color=color,points=[dict(x=r['sent_utc'],y=r['rtt_ms']) for r in probes
                 if r['target']==target and r['status']=='Success' and lower<=epoch(r['sent_utc'])<=upper]) for target,color in zip(TARGETS,COLORS)]
        plotted=([e for e in all_events if e['kind']=='ping_threshold'] if name=='shared-retn-0058.png' else events)
        series.append(dict(name='Logged game Average Ping',color='#d62728',chart_type='Point',
                           points=[dict(x=e['time_utc'],y=e['value']) for e in plotted if lower<=epoch(e['time_utc'])<=upper]))
        spec=dict(name=name,title=title,x_label='Local UTC+05:00; red points are game records, lines are ICMP only',
                  y_label='RTT (ms)',y_min=0,y_max=maximum,series=series)
        if marker:
            spec.update(marker=marker,marker_text='F9: manual mark, no automatic RTT value' if name=='game-only-0108.png' else 'Input replication stop / queue overflow')
        if name=='client-fps-1448.png':
            spec.update(y2_label='Local FPS: threshold events only',y2_max=60,y_interval=30)
            series.append(dict(name='Local FPS events (right axis)',color='#333333',chart_type='Point',secondary=True,
                               points=[dict(x=e['time_utc'],y=e['value']) for e in all_events if e['kind']=='framerate_threshold'
                                       and e.get('metric')=='local_fps' and lower<=epoch(e['time_utc'])<=upper]))
        specs.append(spec)
    series=[]
    for event,code,color in [('spike',1,'#d62728'),('recovery',2,'#1768ac')]:
        series.append(dict(name='F8' if code==1 else 'F9',color=color,chart_type='Point',
                           points=[dict(x=m['observed_utc'],y=code) for m in markers if m['source_run']=='20261114-141126-ee9e460b'
                                   and m['source_kind']=='RegisterHotKey' and m['event']==event]))
    specs.append(dict(name='day-markers.png',title='14 November: recorded manual F8/F9 events, not RTT',
                      x_label='UTC+05:00; repeated presses are not separate incidents',y_label='Event code: F8=1 / F9=2',
                      y_min=0,y_max=3,y_interval=1,series=series))
    return specs


